(bool ok, bytes memory data) = stable.staticcall(abi.encodeCall(IERC20Metadata.decimals, ()));
if (!ok || data.length != 32) revert DecimalsUnavailable(stable);
uint256 actualDecimals = abi.decode(data, (uint256));
if (actualDecimals != decimals) revert DecimalsMismatch(stable, decimals, actualDecimals);
